    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my $recv = defined $1 ? $1 : "";
      my $name = $2;
      next if $name eq "init";
      push @decls, {pkg=>$pkg, name=>$name, path=>$path, line=>$n, recv=>$recv};
    }
  }
  close $fh;
}

# Load all file contents once
my %content; # path => full text
my %pkg_of;  # path => package
for my $path (@all) {
  open my $fh, "<", $path or die "$path: $!";
  local $/;
  my $text = <$fh>;
  close $fh;
  $content{$path} = $text;
  if ($text =~ /^package\s+(\w+)/m) {
    $pkg_of{$path} = $1;
  }
}

sub count_calls {
  my ($pkg, $name, $recv, $decl_path) = @_;
  my $is_method = $recv ne "";
  my $exported = $name =~ /^[A-Z]/;
  my $count = 0;
  my @sites;
  for my $path (@all) {
    my $text = $content{$path};
    my $file_pkg = $pkg_of{$path} // "";
    # strip comments roughly? skip for speed
    if ($is_method) {
      # method: .Name(
      while ($text =~ /\.$name\s*\(/g) {
        $count++;
        push @sites, $path;
      }
    } else {
      # function: pkg.Name( from other packages, Name( from same package
      if ($file_pkg eq $pkg) {
        # same package: Name( but not pkg.Name and not .Name (that's a method-like)
        while ($text =~ /(?<![.\w])$name\s*\(/g) {
          $count++;
          push @sites, $path;
        }
      } else {
        if ($exported) {
          while ($text =~ /\b\Q$pkg\E\.$name\s*\(/g) {
            $count++;
            push @sites, $path;
          }
        }
      }
    }
  }
  # subtract declaration itself (one match in decl file)
  if ($count > 0) {
    $count-- unless $is_method; # same-package Name( includes the func declaration
  }
  return ($count, \@sites);
}

my @results;
for my $d (@decls) {
  my ($count, $sites) = count_calls($d->{pkg}, $d->{name}, $d->{recv}, $d->{path});
  push @results, { %$d, count=>$count, sites=>$sites };
}

@results = sort { $b->{count} <=> $a->{count} } @results;
print "TOP 40\n";
for my $i (0..39) {
  last if $i > $#results;
  my $d = $results[$i];
  my $kind = $d->{recv} ne "" ? "method" : "func";
  printf "%3d  %s.%s [%s] recv=%s  %s:%d\n", $d->{count}, $d->{pkg}, $d->{name}, $kind, $d->{recv}, $d->{path}, $d->{line};
}
ENDPERL
