cat > /tmp/fanin2.pl << 'ENDPERL'
use strict;
use warnings;

open my $ifh, "<", "/tmp/internal_files.txt" or die $!;
my @internal = map { chomp; $_ } <$ifh>;
close $ifh;
open my $afh, "<", "/tmp/all_go_files.txt" or die $!;
my @all = map { chomp; $_ } <$afh>;
close $afh;

my @decls;
for my $path (@internal) {
  open my $fh, "<", $path or die $!;
  my $pkg = "";
  my $n = 0;
  while (my $line = <$fh>) {
    $n++;
    $pkg = $1 if $line =~ /^package\s+(\w+)/;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my $recv = defined $1 ? $1 : "";
      my $name = $2;
      next if $name eq "init";
      push @decls, {pkg=>$pkg, name=>$name, path=>$path, line=>$n, recv=>$recv};
    }
  }
  close $fh;
}

my %content;
my %pkg_of;
for my $path (@all) {
  open my $fh, "<", $path or die "$path: $!";
  local $/;
  my $text = <$fh>;
  close $fh;
  $content{$path} = $text;
  $pkg_of{$path} = $1 if $text =~ /^package\s+(\w+)/m;
}

# Also count across ALL go including tests in proto? already have all except proto/gen and web

sub count_func {
  my ($pkg, $name) = @_;
  my $exported = $name =~ /^[A-Z]/;
  my $count = 0;
  my %files;
  for my $path (@all) {
    my $text = $content{$path};
    my $file_pkg = $pkg_of{$path} // "";
    if ($file_pkg eq $pkg) {
      my $c = () = $text =~ /(?<![.\w])$name\s*\(/g;
      # subtract declaration
      $c-- if $c > 0;
      $count += $c if $c > 0;
      $files{$path} += $c if $c > 0;
    } elsif ($exported) {
      my $c = () = $text =~ /\b\Q$pkg\E\.$name\s*\(/g;
      $count += $c;
      $files{$path} += $c if $c > 0;
    }
  }
  return ($count, scalar keys %files);
}

sub count_method_unique {
  my ($name) = @_;
  my $count = 0;
  my %files;
  for my $path (@all) {
    my $text = $content{$path};
    my $c = () = $text =~ /\.$name\s*\(/g;
    $count += $c;
    $files{$path} += $c if $c > 0;
  }
  return ($count, scalar keys %files);
}

# common method names that collide
my %common = map { $_ => 1 } qw(
  Len Swap Less Next Stop Start Validate Parse Kind Field Register New Close Error String
  matches Send Format Render Compile Run Close String Error Write Read
);

print "=== FUNCTIONS (pkg-qualified + same-pkg) ===\n";
my @funcs = grep { $_->{recv} eq "" } @decls;
my @func_res;
for my $d (@funcs) {
  my ($c, $f) = count_func($d->{pkg}, $d->{name});
  push @func_res, { %$d, count=>$c, files=>$f };
}
@func_res = sort { $b->{count} <=> $a->{count} } @func_res;
for my $i (0..24) {
  last if $i > $#func_res;
  my $d = $func_res[$i];
  printf "%3d calls / %2d files  %s.%s  %s:%d\n", $d->{count}, $d->{files}, $d->{pkg}, $d->{name}, $d->{path}, $d->{line};
}

print "\n=== METHODS with uncommon names ===\n";
my @meth = grep { $_->{recv} ne "" && !$common{$_->{name}} } @decls;
my @meth_res;
for my $d (@meth) {
  my ($c, $f) = count_method_unique($d->{name});
  push @meth_res, { %$d, count=>$c, files=>$f };
}
@meth_res = sort { $b->{count} <=> $a->{count} } @meth_res;
for my $i (0..24) {
  last if $i > $#meth_res;
  my $d = $meth_res[$i];
  printf "%3d calls / %2d files  %s.%s recv=%s  %s:%d\n", $d->{count}, $d->{files}, $d->{pkg}, $d->{name}, $d->{recv}, $d->{path}, $d->{line};
}
ENDPERL
