cat > /tmp/entity_fanin.pl << 'ENDPERL'
use strict;
use warnings;

# Persistent entity types in store package
my @entities = qw(
  User Memo Attachment Inbox Reaction MemoRelation MemoShare
  UserSetting UserIdentity IdentityProvider InstanceSetting
);

# Also consider proto store entities commonly used
my @pb_entities = qw(
  IdentityProvider InstanceSetting AttachmentPayload MemoPayload InboxMessage
  UserSetting InstanceBasicSetting
);

# Collect all go files outside store layer
open my $afh, "<", "/tmp/all_go_files.txt" or die $!;
my @all = map { chomp; $_ } <$afh>;
close $afh;

my @outside;
for my $path (@all) {
  next if $path =~ m{/store/};
  next if $path =~ m{/proto/gen/store/};
  next if $path =~ m{/proto/gen/};
  push @outside, $path;
}

sub pkg_of {
  my ($path) = @_;
  $path =~ s{^/bench/repo/}{};
  $path =~ s{/[^/]+$}{};
  return $path;
}

print "Outside-layer files: ".scalar(@outside)."\n";
print "Outside packages:\n";
my %pkgs;
$pkgs{pkg_of($_)}++ for @outside;
for my $p (sort keys %pkgs) {
  print "  $p ($pkgs{$p} files)\n";
}

print "\n=== store.Entity references ===\n";
for my $ent (@entities) {
  my %hit;
  my $calls = 0;
  for my $path (@outside) {
    open my $fh, "<", $path or die $!;
    local $/;
    my $text = <$fh>;
    close $fh;
    # match store.Entity as a type, not FindEntity/UpdateEntity/DeleteEntity
    my $c = () = $text =~ /(?<![A-Za-z])store\.$ent(?![A-Za-z])/g;
    if ($c > 0) {
      $hit{pkg_of($path)} += $c;
      $calls += $c;
    }
  }
  my $np = scalar keys %hit;
  printf "%2d pkgs / %3d refs  store.%-20s  [%s]\n", $np, $calls, $ent, join(", ", sort keys %hit);
}

print "\n=== storepb.Entity references (outside store+proto) ===\n";
for my $ent (@pb_entities) {
  my %hit;
  my $calls = 0;
  for my $path (@outside) {
    open my $fh, "<", $path or die $!;
    local $/;
    my $text = <$fh>;
    close $fh;
    my $c = () = $text =~ /storepb\.$ent(?![A-Za-z])/g;
    if ($c > 0) {
